import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    idx = 0
    n = int(input_data[idx].strip())
    idx += 1

    categories = []
    for _ in range(n):
        parts = input_data[idx].strip().split()
        idx += 1
        cat_name = parts[0]
        w = int(parts[1])
        words = parts[2:2 + w]
        categories.append((cat_name, set(words)))

    statement_lines = input_data[idx:]
    statement_words = []
    for line in statement_lines:
        statement_words.extend(line.strip().split())

    scores = {}
    for cat_name, cat_words in categories:
        count = 0
        for word in statement_words:
            if word in cat_words:
                count += 1
        scores[cat_name] = count

    if not scores:
        return

    max_score = max(scores.values())
    suggested = [name for name, score in scores.items() if score == max_score]
    suggested.sort()

    for name in suggested:
        print(name)

if __name__ == "__main__":
    main()
